import AppKit

// A document built as ProjectDocument and EditorWindowController build theirs:
// autosavesInPlace true, an untitled then a saved document, a titled window
// with a subtitle. Walks the title bar's views for text after a change.
final class Doc: NSDocument {
    override class var autosavesInPlace: Bool { true }
    override func makeWindowControllers() {
        let window = NSWindow(
            contentRect: NSRect(x: 100, y: 100, width: 900, height: 620),
            styleMask: [.titled, .closable, .miniaturizable, .resizable],
            backing: .buffered, defer: false)
        window.titlebarAppearsTransparent = false
        let controller = NSWindowController(window: window)
        window.subtitle = "1920 × 1080 · 30 fps"
        addWindowController(controller)
    }
    override func data(ofType typeName: String) throws -> Data { Data("x".utf8) }
    override func read(from data: Data, ofType typeName: String) throws {}
    override func writableTypes(for saveOperation: NSDocument.SaveOperationType) -> [String] { ["public.plain-text"] }
    override class var writableTypes: [String] { ["public.plain-text"] }
    override class var readableTypes: [String] { ["public.plain-text"] }
    override func fileNameExtension(forType typeName: String, saveOperation: NSDocument.SaveOperationType) -> String? { "txt" }
}

func texts(_ view: NSView, _ depth: Int = 0, into out: inout [String]) {
    if let field = view as? NSTextField { out.append("\(type(of: view)): '\(field.stringValue)' hidden=\(field.isHiddenOrHasHiddenAncestor)") }
    for sub in view.subviews { texts(sub, depth + 1, into: &out) }
}

func report(_ tag: String, _ doc: Doc) {
    guard let window = doc.windowControllers.first?.window else { return }
    var out: [String] = []
    if let frame = window.contentView?.superview { texts(frame, into: &out) }
    let close = window.standardWindowButton(.closeButton)
    print("[\(tag)] doc.isDocumentEdited=\(doc.isDocumentEdited) window.isDocumentEdited=\(window.isDocumentEdited) title='\(window.title)' subtitle='\(window.subtitle)' close=\(close.map { String(describing: type(of: $0)) } ?? "nil")")
    for line in out { print("   ", line) }
    // Accessibility: the title element's value
    if let closeCell = close {
        print("    close.accessibilityValue=\(String(describing: closeCell.accessibilityValue())) close.isEdited?=\(String(describing: closeCell.value(forKey: "isEdited")))")
    }
}

let app = NSApplication.shared
app.setActivationPolicy(.accessory)

final class Delegate: NSObject, NSApplicationDelegate {
    var doc: Doc!
    var saved: Doc!
    func applicationDidFinishLaunching(_ notification: Notification) {
        doc = Doc()
        doc.makeWindowControllers()
        doc.windowControllers.first?.window?.orderFront(nil)
        report("untitled clean", doc)
        doc.updateChangeCount(.changeDone)
        DispatchQueue.main.asyncAfter(deadline: .now() + 1) {
            report("untitled changed", self.doc)
            let dir = URL(fileURLWithPath: CommandLine.arguments[1])
            let url = dir.appendingPathComponent("edited-probe.txt")
            try? Data("x".utf8).write(to: url)
            do {
                self.saved = try Doc(contentsOf: url, ofType: "public.plain-text")
            } catch { print("open failed", error); exit(1) }
            self.saved.makeWindowControllers()
            self.saved.windowControllers.first?.window?.orderFront(nil)
            report("saved clean", self.saved)
            self.saved.updateChangeCount(.changeDone)
            DispatchQueue.main.asyncAfter(deadline: .now() + 1) {
                report("saved changed", self.saved)
                exit(0)
            }
        }
    }
}
let delegate = Delegate()
app.delegate = delegate
app.run()

