import AppKit

// A row built as InspectorRowView is: an NSStackView overriding menu(for:). The
// popup stand-in is an NSView that, like OptionPopupControl, overrides mouseDown
// and tracking but has no right-click handling and no `menu`. A second child
// is an NSTextField, as OptionFieldControl's field is. Sends a real right-mouse
// event through the window and reports who answered.
var asked: [String] = []
final class Row: NSStackView {
    override func menu(for event: NSEvent) -> NSMenu? {
        asked.append("row.menu(for:)")
        return nil
    }
}
final class Popup: NSView {
    override var isFlipped: Bool { true }
    override var intrinsicContentSize: NSSize { NSSize(width: 120, height: 22) }
    override func mouseDown(with event: NSEvent) { asked.append("popup.mouseDown") }
}
final class Plain: NSView {
    override var intrinsicContentSize: NSSize { NSSize(width: 60, height: 22) }
}

let app = NSApplication.shared
app.setActivationPolicy(.accessory)
let window = NSWindow(
    contentRect: NSRect(x: 100, y: 100, width: 400, height: 100),
    styleMask: [.titled], backing: .buffered, defer: false)
let popup = Popup()
let field = NSTextField(string: "12")
field.isBordered = false
let plain = Plain()
let row = Row(views: [popup, field, plain])
row.orientation = .horizontal
row.frame = NSRect(x: 10, y: 10, width: 380, height: 40)
window.contentView?.addSubview(row)
window.orderFront(nil)
window.contentView?.layoutSubtreeIfNeeded()

func rightClick(_ view: NSView, _ name: String) {
    asked = []
    let p = view.convert(NSPoint(x: view.bounds.midX, y: view.bounds.midY), to: nil)
    let hit = window.contentView?.hitTest(window.contentView!.convert(p, from: nil))
    // A menu that pops tracks modally; the row answers nil so nothing pops.
    let event = NSEvent.mouseEvent(
        with: .rightMouseDown, location: p, modifierFlags: [], timestamp: 0,
        windowNumber: window.windowNumber, context: nil, eventNumber: 1, clickCount: 1, pressure: 1)!
    window.sendEvent(event)
    print("\(name): hit=\(hit.map { String(describing: type(of: $0)) } ?? "nil") answered=\(asked)")
}
rightClick(popup, "popup stand-in")
rightClick(field, "text field")
rightClick(plain, "plain view")
exit(0)

