// A document built as ProjectDocument and EditorWindowController build theirs:
// autosavesInPlace true, an untitled then a saved document, a titled window
// with a subtitle. Walks the title bar's views for text after a change.
setbuf(stdout, nil)
Thread.detachNewThread {
    Thread.sleep(forTimeInterval: 12)
    print("watchdog exit")
    exit(2)
}

final class Doc: NSDocument {
    override class var autosavesInPlace: Bool { true }
    override func makeWindowControllers() {
        let window = NSWindow(
            contentRect: NSRect(x: 100, y: 100, width: 900, height: 620),
            styleMask: [.titled, .closable, .miniaturizable, .resizable],
            backing: .buffered, defer: false)
        window.titlebarAppearsTransparent = false
        let controller = NSWindowController(window: window)
        window.subtitle = "1920 × 1080 · 30 fps"
        addWindowController(controller)
    }
    override func data(ofType typeName: String) throws -> Data { Data("x".utf8) }
    override func read(from data: Data, ofType typeName: String) throws {}
}

func texts(_ view: NSView, into out: inout [String]) {
    if let field = view as? NSTextField {
        out.append("\(type(of: view)): '\(field.stringValue)' hidden=\(field.isHiddenOrHasHiddenAncestor)")
    }
    for sub in view.subviews { texts(sub, into: &out) }
}

func report(_ tag: String, _ doc: Doc) {
    guard let window = doc.windowControllers.first?.window else {
        print("[\(tag)] no window")
        return
    }
    var out: [String] = []
    if let frame = window.contentView?.superview { texts(frame, into: &out) }
    print("[\(tag)] doc.isDocumentEdited=\(doc.isDocumentEdited) window.isDocumentEdited=\(window.isDocumentEdited) title='\(window.title)' subtitle='\(window.subtitle)'")
    for line in out { print("   ", line) }
}

let app = NSApplication.shared
app.setActivationPolicy(.accessory)
print("start")

let doc = Doc()
doc.makeWindowControllers()
doc.windowControllers.first?.window?.orderFront(nil)
report("untitled clean", doc)
doc.updateChangeCount(.changeDone)

let saved = Doc()
saved.fileURL = URL(fileURLWithPath: CommandLine.arguments[1]).appendingPathComponent("edited-probe.txt")
saved.fileType = "public.plain-text"
saved.fileModificationDate = Date()
saved.makeWindowControllers()
saved.windowControllers.first?.window?.orderFront(nil)
report("saved clean", saved)
saved.updateChangeCount(.changeDone)

// Turn the run loop for a moment without app.run(), so the title bar updates.
let until = Date().addingTimeInterval(2)
while Date() < until {
    if let event = app.nextEvent(matching: .any, until: Date().addingTimeInterval(0.1), inMode: .default, dequeue: true) {
        app.sendEvent(event)
    }
}
report("untitled changed", doc)
report("saved changed", saved)
exit(0)

