        addSubview(text)
        NSLayoutConstraint.activate([
            text.leadingAnchor.constraint(equalTo: leadingAnchor, constant: 6),
            text.trailingAnchor.constraint(equalTo: trailingAnchor, constant: -6),
            text.centerYAnchor.constraint(equalTo: centerYAnchor),
        ])
    }
    required init?(coder: NSCoder) { fatalError() }
}

NotificationCenter.default.addObserver(
    forName: NSMenu.didBeginTrackingNotification, object: nil, queue: nil
) { note in
    guard let menu = note.object as? NSMenu else { return }
    asked.append("MENU OPENED: \(menu.items.prefix(4).map(\.title))")
    RunLoop.main.perform(inModes: [.eventTracking, .default, .common]) {
        menu.cancelTrackingWithoutAnimation()
    }
}

